ALTER TABLE str_rn.lessor
    ADD CONSTRAINT chk_lessor_legal_entity_owner
        CHECK (
            is_legal_entity_owner = FALSE OR (
                legal_entity_name IS NOT NULL AND (
                    lessor_oib IS NOT NULL OR (
                        legal_entity_country_id IS NOT NULL AND
                        legal_entity_city IS NOT NULL AND
                        legal_entity_registration_number IS NOT NULL
                    )
                )
            )
        )
